    "source": "-- Proofs, Checked — Chapter 2: Natural Deduction\n-- Companion file for docs/book/02-natural-deduction.md.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch02 docs/book/code/ch02-examples.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\n-- Section 2.3: modus ponens, the arrow-elimination rule.\ntheorem modus_ponens_demo (P Q : Prop) : P -> (P -> Q) -> Q := by\n  intro hp\n  intro hpq\n  apply hpq\n  exact hp\n\n-- Section 2.3: chaining implications (hypothetical syllogism).\ntheorem chain_demo (P Q R : Prop) : (P -> Q) -> (Q -> R) -> P -> R := by\n  intro hpq\n  intro hqr\n  intro hp\n  apply hqr\n  apply hpq\n  exact hp\n\n-- Section 2.4: or-introduction commits to one side.\ntheorem or_intro_demo (P Q : Prop) : P -> P \\/ Q := by\n  intro hp\n  left\n  exact hp\n\n-- Section 2.4: or-elimination is proof by cases.\ntheorem or_elim_demo (P Q R : Prop) : (P -> R) -> (Q -> R) -> P \\/ Q -> R := by\n  intro hpr\n  intro hqr\n  intro h\n  cases h with\n  | left hp =>\n      apply hpr\n      exact hp\n  | right hq =>\n      apply hqr\n      exact hq\n\n-- Section 2.5: `not P` literally is `P -> False`, so this proof is\n-- just `intro` and `exact`.\ntheorem not_is_an_arrow (P : Prop) : (P -> False) -> not P := by\n  intro h\n  exact h\n\n-- Section 2.5: from a contradiction, anything follows (two spellings).\ntheorem explosion_by_hand (P Q : Prop) : P -> not P -> Q := by\n  intro hp\n  intro hnp\n  exfalso\n  apply hnp\n  exact hp\n\ntheorem explosion_short (P Q : Prop) : P -> not P -> Q := by\n  intro hp\n  intro hnp\n  contradiction\n\n-- Section 2.5: modus tollens.\ntheorem modus_tollens_demo (P Q : Prop) : (P -> Q) -> not Q -> not P := by\n  intro hpq\n  intro hnq\n  intro hp\n  apply hnq\n  apply hpq\n  exact hp\n\n-- Section 2.6: disjunctive syllogism — an or, minus one side.\ntheorem disjunctive_syllogism_demo (P Q : Prop) : P \\/ Q -> not P -> Q := by\n  intro h\n  intro hnp\n  cases h with\n  | left hp =>\n      contradiction\n  | right hq =>\n      exact hq\n\n-- Section 2.7: `<->` is a conjunction of two implications, so `split`\n-- opens it and each half starts with `intro`.\ntheorem iff_swap_demo (P Q : Prop) : P /\\ Q <-> Q /\\ P := by\n  split\n  intro h\n  split\n  exact h.right\n  exact h.left\n  intro h\n  split\n  exact h.right\n  exact h.left\n"
