    "source": "-- Proofs, Checked — Chapter 6: common mistakes.\n-- INTENDED TO FAIL. Every theorem in this file contains a deliberate\n-- mistake discussed in the \"Common mistakes\" section of the chapter.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch06 docs/book/code/ch06-mistakes.ctea\n\nmode constructive\n\nsort Student\n\nconst ana : Student\n\npred TakesCS(Student)\n\ndef CS : Set Student := { x : Student | TakesCS(x) }\n\n-- Mistake 1: refl on a set equality. Sets are equal by extensionality,\n-- not by looking identical.\ntheorem sets_equal_by_staring (T : Type) (A B : Set T)\n  : union(A, B) = union(B, A) := by\n  refl\n\n-- Mistake 2: a subset hypothesis is a forall, and wants the element first.\ntheorem subset_skips_a_step (T : Type) (A B : Set T) (a : T) : A subset B -> a in A -> a in B := by\n  intro h\n  intro ha\n  exact h ha\n\n-- Mistake 3: subset is not symmetric — and watch how the failure looks.\ntheorem subset_flip (T : Type) (A B : Set T) : A subset B -> B subset A := by\n  intro h\n  simp\n  intro x\n  intro hx\n  apply h\n  exact hx\n\n-- Mistake 4: an element is not a one-element set.\ntheorem element_confusion : ana subset CS := by\n  simp\n"
