    "source": "-- Proofs, Checked — Chapter 7: Relations: Structure Between Things\n-- Companion file for docs/book/07-relations.md.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch07 docs/book/code/ch07-examples.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\nsort Person\n\npred Knows(Person, Person)\n\n-- Section 7.2: the three properties, stated once, over any relation.\ndef Reflexive (T : Type) (R : T -> T -> Prop) : Prop := forall x : T, R(x, x)\n\ndef Symmetric (T : Type) (R : T -> T -> Prop) : Prop := forall x y : T, R(x, y) -> R(y, x)\n\ndef Transitive (T : Type) (R : T -> T -> Prop) : Prop := forall x y z : T, R(x, y) -> R(y, z) -> R(x, z)\n\ndef Equivalence (T : Type) (R : T -> T -> Prop) : Prop := Reflexive(R) /\\ Symmetric(R) /\\ Transitive(R)\n\n-- Section 7.3: equality passes all three tests — Chapter 5 as a report card.\ntheorem eq_reflexive (T : Type) : Reflexive(fun x y : T => x = y) := by\n  unfold Reflexive\n  intro x\n  refl\n\ntheorem eq_symmetric (T : Type) : Symmetric(fun x y : T => x = y) := by\n  unfold Symmetric\n  intro x\n  intro y\n  intro h\n  exact eq_symm h\n\ntheorem eq_transitive (T : Type) : Transitive(fun x y : T => x = y) := by\n  unfold Transitive\n  intro x\n  intro y\n  intro z\n  intro h1\n  intro h2\n  exact eq_trans h1 h2\n\n-- Section 7.4: le is reflexive...\ntheorem le_reflexive : Reflexive(fun x y : Nat => x <= y) := by\n  unfold Reflexive\n  intro x\n  exact le_refl\n\n-- ...but NOT symmetric, and we can prove that it isn't.\ntheorem le_not_symmetric : not Symmetric(fun x y : Nat => x <= y) := by\n  intro h\n  simp at h\n  have h01 : 1 <= 0\n  apply h 0 1\n  trivial\n  apply succ_not_le_zero {n := 0}\n  exact h01\n\n-- Section 7.5: building a symmetric relation out of an unruly one.\ntheorem mutual_knowing_symmetric\n  : Symmetric(fun x y : Person => Knows(x, y) /\\ Knows(y, x)) := by\n  unfold Symmetric\n  intro x\n  intro y\n  intro h\n  split\n  exact h.right\n  exact h.left\n\n-- Section 7.6: the payoff — congruence mod m is an equivalence relation.\n-- ModEq(m, x, y) and its refl/sym/trans theorems come from std/modular.ctea.\ntheorem modeq_reflexive (m : Nat) : Reflexive(fun x y : Nat => ModEq(m, x, y)) := by\n  unfold Reflexive\n  intro x\n  exact modeq_refl\n\ntheorem modeq_symmetric (m : Nat) : Symmetric(fun x y : Nat => ModEq(m, x, y)) := by\n  unfold Symmetric\n  intro x\n  intro y\n  intro h\n  exact modeq_sym m x y h\n\ntheorem modeq_transitive (m : Nat) : Transitive(fun x y : Nat => ModEq(m, x, y)) := by\n  unfold Transitive\n  intro x\n  intro y\n  intro z\n  intro h1\n  intro h2\n  apply modeq_trans\n  exact h1\n  exact h2\n\n-- The whole bundle in one statement: an equivalence relation.\ntheorem modeq_equivalence (m : Nat) : Equivalence(fun x y : Nat => ModEq(m, x, y)) := by\n  unfold Equivalence\n  split\n  exact modeq_reflexive {m := m}\n  split\n  exact modeq_symmetric {m := m}\n  exact modeq_transitive {m := m}\n\n-- Section 7.6: a concrete residue fact — 27 o'clock is 3 o'clock.\n-- The witnesses say: 27 + 12*0 and 3 + 12*2 are the same number.\ntheorem clock_27_is_3 : ModEq(12, 27, 3) := by\n  unfold ModEq\n  exists 0\n  exists 2\n  refl\n"
