    "source": "-- Proofs, Checked — Chapter 7: exercise solutions.\n-- Spoilers! Try docs/book/code/ch07-exercises.ctea yourself first.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch07 docs/book/code/ch07-solutions.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\nsort Person\n\npred Happy(Person)\npred Likes(Person, Person)\n\ndef Reflexive (T : Type) (R : T -> T -> Prop) : Prop := forall x : T, R(x, x)\n\ndef Symmetric (T : Type) (R : T -> T -> Prop) : Prop := forall x y : T, R(x, y) -> R(y, x)\n\ndef Transitive (T : Type) (R : T -> T -> Prop) : Prop := forall x y z : T, R(x, y) -> R(y, z) -> R(x, z)\n\ndef Equivalence (T : Type) (R : T -> T -> Prop) : Prop := Reflexive(R) /\\ Symmetric(R) /\\ Transitive(R)\n\ndef SameMood (x y : Person) : Prop := Happy(x) <-> Happy(y)\n\n-- Exercise 7.1. 23 + 10*0 = 23 and 3 + 10*2 = 23.\ntheorem ex7_1 : ModEq(10, 23, 3) := by\n  unfold ModEq\n  exists 0\n  exists 2\n  refl\n\n-- Exercise 7.2\ntheorem ex7_2 : Reflexive(fun x y : Nat => Divides(x, y)) := by\n  unfold Reflexive\n  intro x\n  exact divides_refl\n\n-- Exercise 7.3\ntheorem ex7_3 : Symmetric(fun x y : Person => Likes(x, y) /\\ Likes(y, x)) := by\n  unfold Symmetric\n  intro x\n  intro y\n  intro h\n  split\n  exact h.right\n  exact h.left\n\n-- Exercise 7.4\ntheorem ex7_4 : Transitive(fun x y : Nat => Divides(x, y)) := by\n  unfold Transitive\n  intro x\n  intro y\n  intro z\n  intro h1\n  intro h2\n  apply divides_trans\n  exact h1\n  exact h2\n\n-- Exercise 7.5\ntheorem ex7_5 : Reflexive(SameMood) := by\n  unfold Reflexive\n  intro x\n  unfold SameMood\n  split\n  intro h\n  exact h\n  intro h\n  exact h\n\n-- Exercise 7.6\ntheorem ex7_6 : Symmetric(SameMood) := by\n  unfold Symmetric\n  intro x\n  intro y\n  intro h\n  unfold SameMood\n  split\n  exact h.right\n  exact h.left\n\n-- Exercise 7.7\ntheorem ex7_7 : Transitive(SameMood) := by\n  unfold Transitive\n  intro x\n  intro y\n  intro z\n  intro h1\n  intro h2\n  unfold SameMood\n  split\n  intro hx\n  apply h2.left\n  apply h1.left\n  exact hx\n  intro hz\n  apply h1.right\n  apply h2.right\n  exact hz\n\n-- Exercise 7.8\ntheorem ex7_8 : Equivalence(SameMood) := by\n  unfold Equivalence\n  split\n  exact ex7_5\n  split\n  exact ex7_6\n  exact ex7_7\n"
