    "source": "-- Proofs, Checked — Chapter 8: exercise solutions.\n-- Spoilers! Try docs/book/code/ch08-exercises.ctea yourself first.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch08 docs/book/code/ch08-solutions.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\nsort Person\n\nconst alice : Person\n\n-- Exercise 8.1\ntheorem ex8_1 : Total(fun x y : Nat => x * x = y) := by\n  unfold Total\n  intro x\n  exists x * x\n  refl\n\n-- Exercise 8.2\ntheorem ex8_2 : SingleValued(fun x y : Nat => x * x = y) := by\n  unfold SingleValued\n  intro x\n  intro y1\n  intro y2\n  intro h1\n  intro h2\n  rewrite <- h1\n  exact h2\n\n-- Exercise 8.3. simp computes x + 2 to succ(succ(x)), and then\n-- succ_inj peels the successors two at a time.\ntheorem ex8_3 : Injective(fun x y : Nat => x + 2 = y) := by\n  unfold Injective\n  intro x1\n  intro x2\n  intro y\n  intro h1\n  intro h2\n  simp at h1\n  simp at h2\n  apply succ_inj\n  apply succ_inj\n  rewrite -> h1\n  exact eq_symm h2\n\n-- Exercise 8.4\ntheorem ex8_4 : Surjective(fun x y : Nat => x = y) := by\n  unfold Surjective\n  intro y\n  exists y\n  refl\n\n-- Exercise 8.5\ntheorem ex8_5 : Total(fun x y : Person => y = alice) := by\n  unfold Total\n  intro x\n  exists alice\n  refl\n\n-- Exercise 8.6\ntheorem ex8_6 : SingleValued(fun x y : Person => y = alice) := by\n  unfold SingleValued\n  intro x\n  intro y1\n  intro y2\n  intro h1\n  intro h2\n  rewrite -> h2\n  exact h1\n\n-- Exercise 8.7\ntheorem ex8_7\n  (F : Person -> Person -> Prop)\n  (G : Person -> Person -> Prop)\n  : Surjective(F)\n    -> Surjective(G)\n    -> forall z : Person, exists x : Person, exists y : Person, F(x, y) /\\ G(y, z) := by\n  intro hf\n  intro hg\n  exact compose_surjective {A := Person; B := Person; C := Person; F := F; G := G} hf hg\n"
