    "source": "-- Proofs, Checked — Chapter 9: Induction: Climbing the Number Line\n-- Companion file for docs/book/09-induction.md.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch09 docs/book/code/ch09-examples.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\n-- Section 9.2: numerals are shorthand for towers of succ. Both sides\n-- of this equality compute down to the same tower, so `refl` closes it.\ntheorem two_plus_three : 2 + 3 = 5 := by\n  refl\n\n-- Section 9.3: the additive identities are pure computation. No\n-- induction needed -- `refl` normalizes both sides itself.\ntheorem add_zero_left_demo (n : Nat) : 0 + n = n := by\n  refl\n\ntheorem add_zero_right_demo (n : Nat) : n + 0 = n := by\n  refl\n\n-- Section 9.5: the first real induction proof. In the succ arm, the\n-- goal after `simp` is *exactly* the induction hypothesis.\ntheorem sub_self_demo (n : Nat) : n - n = 0 := by\n  induction n with\n  | zero =>\n      refl\n  | succ k ih =>\n      simp\n      exact ih\n\n-- Section 9.6: commutativity of addition. The succ arm needs both\n-- computation (`simp`) and the induction hypothesis (`rewrite ih`).\n-- This is `add_comm` in std/nat.ctea.\ntheorem add_comm_demo (n m : Nat) : n + m = m + n := by\n  induction n with\n  | zero =>\n      simp\n      refl\n  | succ k ih =>\n      simp\n      rewrite <- ih\n      refl\n\n-- Section 9.8: if a dependent premise was introduced too early,\n-- `revert` restores the implication goal before induction.\ntheorem revert_before_induction (n : Nat) : n <= n -> n <= n := by\n  intro h\n  revert h\n  induction n with\n  | zero =>\n      intro h\n      exact h\n  | succ k ih =>\n      intro h\n      exact h\n"
