    "source": "-- Proofs, Checked — Chapter 10: Recursion and Data: Building Your Own Worlds\n-- Companion file for docs/book/10-recursion-data.md.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch10 docs/book/code/ch10-examples.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\n-- Section 10.2: a first recursive definition over Nat.\ndefrec double (n : Nat) : Nat\n| zero => 0\n| succ k rec => succ(succ(rec))\n\n-- Concrete computation: running the program IS checking the proof.\ntheorem double_three : double(3) = 6 := by\n  refl\n\n-- Symbolic computation: the successor equation, straight from the arm.\ntheorem double_succ_demo (n : Nat) : double(succ(n)) = succ(succ(double(n))) := by\n  refl\n\n-- Recursion and induction are twins: a fact about a recursive\n-- definition, proved by induction along the same skeleton.\ntheorem double_is_add (n : Nat) : double(n) = n + n := by\n  induction n with\n  | zero =>\n      refl\n  | succ k ih =>\n      simp\n      rewrite <- ih\n      refl\n\n-- Section 10.2: summing 1 + 2 + ... + n.\ndefrec sumto (n : Nat) : Nat\n| zero => 0\n| succ k rec => succ(k) + rec\n\ntheorem sumto_four : sumto(4) = 10 := by\n  refl\n\n-- Section 10.4: a binary definition. The recursion runs on the first\n-- argument; m just comes along for the ride.\ndefrec addl (n : Nat) (m : Nat) : Nat\n| zero => m\n| succ k rec => succ(rec)\n\n-- The two defining equations compute...\ntheorem addl_zero_left (m : Nat) : addl(0, m) = m := by\n  refl\n\ntheorem addl_succ_left (n m : Nat) : addl(succ(n), m) = succ(addl(n, m)) := by\n  refl\n\n-- ...but the mirror-image fact does not: addl(n, 0) is stuck until we\n-- know whether n is zero or a successor. Induction to the rescue.\ntheorem addl_zero_right (n : Nat) : addl(n, 0) = n := by\n  induction n with\n  | zero =>\n      refl\n  | succ k ih =>\n      simp\n      rewrite -> ih\n      refl\n\n-- Section 10.5: lists (declared in std/list.ctea: nil, cons(Nat, List Nat))\n-- and their recursive functions compute the same way.\ntheorem length_demo : length(cons(7, cons(4, nil))) = 2 := by\n  refl\n\n-- Our own defrec over List Nat: the sum of the elements.\ndefrec sum (l : List Nat) : Nat\n| nil => 0\n| cons h t rec => h + rec\n\ntheorem sum_demo : sum(cons(1, cons(2, cons(3, nil)))) = 6 := by\n  refl\n\n-- append (std/list.ctea) is a binary defrec, like addl. Its recursion\n-- equations are theorems, not axioms -- refl proves both.\ntheorem append_demo : append(cons(1, nil), cons(2, nil)) = cons(1, cons(2, nil)) := by\n  refl\n\ntheorem append_cons_demo (h : Nat) (t : List Nat) (l : List Nat)\n  : append(cons(h, t), l) = cons(h, append(t, l)) := by\n  refl\n\n-- A binary defrec can even build a list from a number.\ndefrec replicate (n : Nat) (x : Nat) : List Nat\n| zero => nil\n| succ k rec => cons(x, rec)\n\ntheorem replicate_two : replicate(2, 9) = cons(9, cons(9, nil)) := by\n  refl\n\n-- Section 10.6: the same fact twice -- once from definitions alone,\n-- once through the library's one honest axiom. Compare the accepted\n-- lines the checker prints for these two.\ntheorem divides_5_20_direct : Divides(5, 20) := by\n  unfold Divides\n  exists 4\n  refl\n\ntheorem divides_5_20_via_modeq : Divides(5, 20) := by\n  apply modeq_zero_to_divides\n  unfold ModEq\n  exists 0\n  exists 4\n  refl\n"
