    "source": "-- Proofs, Checked — Chapter 11: exercises.\n-- Replace each `sorry` with a real proof. The data type and the\n-- recursive definitions are provided.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch11 docs/book/code/ch11-exercises.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\ndefrec sum (l : List Nat) : Nat\n| nil => 0\n| cons h t rec => h + rec\n\ndata Tree\n| leaf\n| node(Tree, Nat, Tree)\n\ndefrec size (t : Tree) : Nat\n| leaf => 0\n| node l v r recl recr => succ(recl + recr)\n\ndefrec mirror (t : Tree) : Tree\n| leaf => leaf\n| node l v r recl recr => node(recr, v, recl)\n\ndefrec leaves (t : Tree) : Nat\n| leaf => 1\n| node l v r recl recr => recl + recr\n\n-- Exercise 11.1 (warm-up). A concrete tree: count before you prove.\ntheorem ex11_1 : size(node(node(leaf, 1, leaf), 2, leaf)) = 2 := by\n  sorry\n\n-- Exercise 11.2. Associativity of append. Induct on l1 -- the\n-- argument append recurses on. The skeleton is the same as\n-- length_append_demo.\ntheorem ex11_2 (l1 : List Nat) (l2 : List Nat) (l3 : List Nat)\n  : append(append(l1, l2), l3) = append(l1, append(l2, l3)) := by\n  sorry\n\n-- Exercise 11.3. Sum distributes over append. The cons arm needs one\n-- extra step beyond the induction hypothesis:\n-- rewrite add_assoc {n := h; m := sum(t); k := sum(l2)}.\ntheorem ex11_3 (l1 : List Nat) (l2 : List Nat)\n  : sum(append(l1, l2)) = sum(l1) + sum(l2) := by\n  sorry\n\n-- Exercise 11.4. Mirroring twice is doing nothing. Two induction\n-- hypotheses, two rewrites.\ntheorem ex11_4 (t : Tree) : mirror(mirror(t)) = t := by\n  sorry\n\n-- Exercise 11.5. Mirroring preserves the leaf count. Model the proof\n-- on mirror_size_demo, add_comm and all.\ntheorem ex11_5 (t : Tree) : leaves(mirror(t)) = leaves(t) := by\n  sorry\n\n-- Exercise 11.6 (challenge). Every tree has one more leaf than it has\n-- nodes. In the node arm, after the two induction hypotheses, you\n-- will want add_succ_right {n := size(l); m := size(r)}.\ntheorem ex11_6 (t : Tree) : leaves(t) = succ(size(t)) := by\n  sorry\n"
