    "source": "-- Proofs, Checked — Chapter 11: exercise solutions.\n-- Spoilers! Try docs/book/code/ch11-exercises.ctea yourself first.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch11 docs/book/code/ch11-solutions.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\ndefrec sum (l : List Nat) : Nat\n| nil => 0\n| cons h t rec => h + rec\n\ndata Tree\n| leaf\n| node(Tree, Nat, Tree)\n\ndefrec size (t : Tree) : Nat\n| leaf => 0\n| node l v r recl recr => succ(recl + recr)\n\ndefrec mirror (t : Tree) : Tree\n| leaf => leaf\n| node l v r recl recr => node(recr, v, recl)\n\ndefrec leaves (t : Tree) : Nat\n| leaf => 1\n| node l v r recl recr => recl + recr\n\n-- Exercise 11.1\ntheorem ex11_1 : size(node(node(leaf, 1, leaf), 2, leaf)) = 2 := by\n  refl\n\n-- Exercise 11.2\ntheorem ex11_2 (l1 : List Nat) (l2 : List Nat) (l3 : List Nat)\n  : append(append(l1, l2), l3) = append(l1, append(l2, l3)) := by\n  induction l1 with\n  | nil =>\n      refl\n  | cons h t ih =>\n      simp\n      rewrite -> ih\n      refl\n\n-- Exercise 11.3\ntheorem ex11_3 (l1 : List Nat) (l2 : List Nat)\n  : sum(append(l1, l2)) = sum(l1) + sum(l2) := by\n  induction l1 with\n  | nil =>\n      refl\n  | cons h t ih =>\n      simp\n      rewrite -> ih\n      rewrite <- add_assoc {n := h; m := sum(t); k := sum(l2)}\n      refl\n\n-- Exercise 11.4\ntheorem ex11_4 (t : Tree) : mirror(mirror(t)) = t := by\n  induction t with\n  | leaf =>\n      refl\n  | node l v r ihl ihr =>\n      simp\n      rewrite -> ihl\n      rewrite -> ihr\n      refl\n\n-- Exercise 11.5\ntheorem ex11_5 (t : Tree) : leaves(mirror(t)) = leaves(t) := by\n  induction t with\n  | leaf =>\n      refl\n  | node l v r ihl ihr =>\n      simp\n      rewrite -> ihl\n      rewrite -> ihr\n      rewrite -> add_comm {n := leaves(l); m := leaves(r)}\n      refl\n\n-- Exercise 11.6\ntheorem ex11_6 (t : Tree) : leaves(t) = succ(size(t)) := by\n  induction t with\n  | leaf =>\n      refl\n  | node l v r ihl ihr =>\n      simp\n      rewrite -> ihl\n      rewrite -> ihr\n      rewrite -> add_succ_right {n := size(l); m := size(r)}\n      refl\n"
