    "source": "-- Proofs, Checked — Chapter 12: Strong Induction, and Where to Go Next\n-- Companion file for docs/book/12-strong-induction.md.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch12 docs/book/code/ch12-examples.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\n-- Section 12.3: first contact with strong_induction. Same theorem as\n-- Chapter 9's sub_self_demo, proved with the stronger principle: the\n-- step goal hands us P(m) for EVERY m <= k, and we use it at m = k.\ntheorem sub_self_strong (n : Nat) : n - n = 0 := by\n  apply strong_induction {P := fun m : Nat => m - m = 0; n := n}\n  refl\n  intro k\n  intro hk\n  simp\n  apply hk\n  exact le_refl\n\n-- Section 12.4: two order lemmas, by ordinary Chapter 9 induction.\n-- Neither is in std/nat.ctea, so we prove them here.\ntheorem le_n_succ_n (n : Nat) : n <= succ(n) := by\n  induction n with\n  | zero =>\n      simp\n      trivial\n  | succ k ih =>\n      simp\n      exact ih\n\ntheorem pred_le (n : Nat) : pred(n) <= n := by\n  induction n with\n  | zero =>\n      simp\n      trivial\n  | succ k ih =>\n      simp\n      exact le_n_succ_n\n\n-- Section 12.4: the hallway of bulbs. Bulb succ(k) copies the bulb\n-- TWO positions back (pred(k), not k), so ordinary induction is one\n-- rung short -- see the mistakes file. Strong induction covers it.\nfunc bulb : Nat -> Nat\n\naxiom bulb_zero : bulb(0) = 0\naxiom bulb_step (k : Nat) : bulb(succ(k)) = bulb(pred(k))\n\ntheorem all_bulbs_off (n : Nat) : bulb(n) = 0 := by\n  apply strong_induction {P := fun m : Nat => bulb(m) = 0; n := n}\n  exact bulb_zero\n  intro k\n  intro hk\n  rewrite -> bulb_step {k := k}\n  apply hk\n  exact pred_le\n"
