    "source": "-- Proofs, Checked — Chapter 12: common mistakes.\n-- INTENDED TO FAIL. Each theorem contains a deliberate mistake\n-- discussed in the \"Common mistakes\" section of the chapter.\n--\n--   cargo run -p hol_cli -- --course courses/proofs-checked.json --section ch12 docs/book/code/ch12-mistakes.ctea\n\nimport ../../../std/prelude.ctea\n\nmode constructive\n\nfunc bulb : Nat -> Nat\n\naxiom bulb_zero : bulb(0) = 0\naxiom bulb_step (k : Nat) : bulb(succ(k)) = bulb(pred(k))\n\n-- Mistake 1: ordinary induction is one rung short. The induction\n-- hypothesis speaks about k, but after rewriting with bulb_step the\n-- goal speaks about pred(k).\ntheorem one_rung_short (n : Nat) : bulb(n) = 0 := by\n  induction n with\n  | zero =>\n      exact bulb_zero\n  | succ k ih =>\n      rewrite -> bulb_step {k := k}\n      exact ih\n\n-- Mistake 2: applying strong_induction without saying what P is. Left\n-- to guess, the checker picks a predicate that ignores its argument;\n-- spell it out as a lambda.\ntheorem which_predicate (n : Nat) : bulb(n) = 0 := by\n  apply strong_induction\n  exact bulb_zero\n"
